"""Array alias models generated by hook 0800 (e.g. ``TagSet``) validate their items (#394)."""

from __future__ import annotations

import pytest
from pydantic import ValidationError


def test_semantic_item_alias_model_builds_and_brands_items():
    from camunda_orchestration_sdk.models.tag_set import TagSet
    from camunda_orchestration_sdk.semantic_types import Tag

    tags = TagSet.model_validate(["alpha", "beta:1"])

    assert tags.root == ["alpha", "beta:1"]
    assert all(type(tag) is Tag for tag in tags.root)
    assert tags.model_dump() == ["alpha", "beta:1"]
    assert TagSet.model_json_schema()["type"] == "array"


@pytest.mark.parametrize(
    ("items", "message"),
    [
        ([1], "expected str"),
        (["1starts-with-digit"], "pattern"),
        (["dup", "dup"], "uniqueItems"),
        ([f"t{i}" for i in range(11)], "maxItems 10"),
    ],
)
def test_semantic_item_alias_model_rejects_invalid_items(
    items: list[object], message: str
):
    from camunda_orchestration_sdk.models.tag_set import TagSet

    with pytest.raises(ValidationError, match=message):
        TagSet.model_validate(items)


def test_item_error_messages_interpolate_the_index():
    """No generated model may carry a literal ``{_i}``: the index must be interpolated."""
    import ast
    from pathlib import Path

    import camunda_orchestration_sdk

    models_dir = Path(camunda_orchestration_sdk.__file__).parent / "models"
    offenders: list[str] = []
    for model_file in sorted(models_dir.glob("*.py")):
        tree = ast.parse(model_file.read_text(encoding="utf-8"))
        joined_parts = {
            id(part)
            for node in ast.walk(tree)
            if isinstance(node, ast.JoinedStr)
            for part in node.values
        }
        offenders.extend(
            f"{model_file.name}:{node.lineno}"
            for node in ast.walk(tree)
            if isinstance(node, ast.Constant)
            and isinstance(node.value, str)
            and "{_i}" in node.value
            and id(node) not in joined_parts
        )

    assert not offenders, f"Literal '{{_i}}' in item error messages: {offenders}"


@pytest.mark.parametrize(
    ("item_type", "base", "good", "bad"),
    [
        ("string", str, "a", 1),
        ("integer", int, 7, "7"),
        ("integer", int, 7, True),
        ("number", float, 1.5, "1.5"),
        ("number", float, 2, True),
        ("boolean", bool, True, 1),
    ],
)
def test_semantic_item_converter_checks_the_primitive_base_type(
    tmp_path, item_type: str, base: type, good: object, bad: object
):
    """The emitted item converter must accept every primitive base type, not only str."""
    import importlib.util
    import sys
    from pathlib import Path

    hooks = Path(__file__).resolve().parents[2] / "hooks" / "post_gen"
    sys.path.insert(0, str(hooks))
    try:
        spec = importlib.util.spec_from_file_location(
            "_hook0800", hooks / "0800_generate_composite_alias_models.py"
        )
        assert spec and spec.loader
        hook = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(hook)
    finally:
        sys.path.remove(str(hooks))

    hook._emit_array_alias_model(
        tmp_path, "ItemSet", {"type": item_type, "x-semantic-type": "Item"}, {}
    )
    source = (tmp_path / "item_set.py").read_text()
    source = source.replace("from ..semantic_types import Item", "")
    from typing import Any

    item_base: Any = base
    ns: dict[str, Any] = {
        "Item": bool if base is bool else type("Item", (item_base,), {})
    }
    exec(compile(source, "item_set.py", "exec"), ns)
    model: Any = ns["ItemSet"]
    assert model.model_validate([good]).root == [good]
    with pytest.raises(ValidationError, match=f"expected {base.__name__}"):
        model.model_validate([bad])


def _load_hook(hooks_dir, name: str):
    import importlib.util
    import sys

    sys.path.insert(0, str(hooks_dir))
    try:
        spec = importlib.util.spec_from_file_location(
            f"_hook_{name}", hooks_dir / name
        )
        assert spec and spec.loader
        hook = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(hook)
        return hook
    finally:
        sys.path.remove(str(hooks_dir))


def test_number_semantic_item_converter_casts_int_to_float(tmp_path):
    """A number semantic item must accept int input: hook 0700 emits a float-only
    constructor, so hook 0800's converter must cast accepted ints to float before
    constructing, or a valid item such as 2 raises TypeError (#395 review)."""
    from pathlib import Path
    from typing import Any

    hooks = Path(__file__).resolve().parents[2] / "hooks" / "post_gen"
    hook0700 = _load_hook(hooks, "0700_generate_semantic_types.py")
    hook0800 = _load_hook(hooks, "0800_generate_composite_alias_models.py")

    # Emit the semantic constructor exactly as hook 0700 does for a number alias.
    pkg = tmp_path / "pkg"
    hook0700._emit_semantic_types_py(pkg, {"Score": {"type": "number", "constraints": {}}})
    sem_ns: dict[str, Any] = {}
    exec(
        compile(
            (pkg / "camunda_orchestration_sdk" / "semantic_types.py").read_text(),
            "semantic_types.py",
            "exec",
        ),
        sem_ns,
    )

    # Emit the array alias converter exactly as hook 0800 does for number items.
    models_dir = tmp_path / "models"
    models_dir.mkdir()
    hook0800._emit_array_alias_model(
        models_dir, "ScoreSet", {"type": "number", "x-semantic-type": "Score"}, {}
    )
    source = (models_dir / "score_set.py").read_text()
    source = source.replace("from ..semantic_types import Score", "")
    alias_ns: dict[str, Any] = {"Score": sem_ns["Score"]}
    exec(compile(source, "score_set.py", "exec"), alias_ns)

    model: Any = alias_ns["ScoreSet"]
    score_type = sem_ns["Score"]

    # An int item validates instead of raising the float-only constructor's TypeError,
    # and is stored as the float-based semantic type.
    validated = model.model_validate([2, 1.5])
    assert validated.root == [2.0, 1.5]
    assert all(type(item) is score_type for item in validated.root)
    assert all(isinstance(item, float) for item in validated.root)

    # bool and non-numeric items are still rejected.
    with pytest.raises(ValidationError, match="expected float"):
        model.model_validate([True])
    with pytest.raises(ValidationError, match="expected float"):
        model.model_validate(["2"])


@pytest.mark.parametrize(
    ("item_type", "json_type"),
    [
        ("string", "string"),
        ("integer", "integer"),
        ("number", "number"),
        ("boolean", "boolean"),
    ],
)
def test_semantic_item_alias_model_carries_json_schema_metadata(
    tmp_path, item_type: str, json_type: str
):
    """A bare ``PlainValidator`` has no JSON-schema metadata, so
    ``model_json_schema()`` raises ``PydanticInvalidForJsonSchema`` on pydantic
    2.8.x, which the published ``pydantic>=2`` requirement still supports (#395
    review). The emitted item annotation must carry ``WithJsonSchema`` with the
    item's primitive JSON type, for every base type."""
    from pathlib import Path
    from typing import Any

    hooks = Path(__file__).resolve().parents[2] / "hooks" / "post_gen"
    hook0800 = _load_hook(hooks, "0800_generate_composite_alias_models.py")

    models_dir = tmp_path / "models"
    models_dir.mkdir()
    hook0800._emit_array_alias_model(
        models_dir, "ItemSet", {"type": item_type, "x-semantic-type": "Item"}, {}
    )
    source = (models_dir / "item_set.py").read_text()
    assert "WithJsonSchema" in source
    source = source.replace("from ..semantic_types import Item", "")
    item_base: Any = {"string": str, "integer": int, "number": float, "boolean": bool}[
        item_type
    ]
    ns: dict[str, Any] = {
        "Item": bool if item_base is bool else type("Item", (item_base,), {})
    }
    exec(compile(source, "item_set.py", "exec"), ns)

    model: Any = ns["ItemSet"]
    for mode in ("validation", "serialization"):
        schema = model.model_json_schema(mode=mode)
        assert schema["type"] == "array"
        assert schema["items"]["type"] == json_type
